@section('css')
    <style>
        .icon-grid-six {
            --tabler-icon-size: 24px;
            --tabler-icon-color: #000000;
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
            gap: 0.75rem;
            justify-items: center;
            align-items: stretch;
            text-align: center;
        }

        .icon-grid-six .inner-icon-item .avatar-title i {
            font-size: var(--tabler-icon-size) !important;
            color: var(--tabler-icon-color);
            transition: color 0.2s ease-in-out, font-size 0.2s ease-in-out;
        }

        .icon-toolbar {
            background: linear-gradient(180deg, rgba(13, 110, 253, 0.05), rgba(13, 110, 253, 0.01));
            border: 1px dashed rgba(33, 37, 41, 0.2);
            border-radius: 0.75rem;
            padding: 1rem;
        }

        .icon-toolbar .toolbar-label {
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 0.04em;
            color: #6c757d;
            margin-bottom: 0.35rem;
            display: inline-block;
            font-weight: 600;
        }

        .icon-toolbar .form-range {
            cursor: pointer;
        }

        .icon-toolbar .toolbar-control {
            display: flex;
            flex-direction: column;
            height: 100%;
        }

        .icon-toolbar .color-control {
            min-height: 38px;
            border-radius: 0.5rem;
            padding: 0.2rem 0.3rem;
        }

        .icon-toolbar .toolbar-reset {
            min-height: 38px;
            height: 100%;
            border-radius: 0.5rem;
            padding-inline: 0.85rem;
            display: inline-flex;
            align-items: center;
            justify-content: center;
        }

        .snippet-board {
            border: 1px dashed rgba(33, 37, 41, 0.2);
            border-radius: 0.75rem;
            background-color: #f8f9fa;
            overflow: hidden;
            margin-bottom: 1rem;
        }

        .snippet-cell {
            padding: 0.9rem 1rem;
            min-height: 92px;
            display: flex;
            flex-direction: column;
            justify-content: center;
        }

        .snippet-cell+.snippet-cell {
            border-left: 1px dashed rgba(33, 37, 41, 0.2);
        }

        .snippet-title {
            font-size: 0.72rem;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: #6c757d;
            margin-bottom: 0.45rem;
            font-weight: 600;
        }

        .snippet-preview {
            font-size: var(--tabler-icon-size, 24px);
            color: var(--tabler-icon-color, #000000);
            line-height: 1;
            min-height: 28px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s ease-in-out;
        }

        .snippet-preview i {
            font-size: var(--tabler-icon-size, 24px) !important;
            color: currentColor;
            transition: font-size 0.2s ease-in-out;
        }

        .snippet-cell.centered {
            align-items: center;
            text-align: center;
        }

        .snippet-icon-name {
            margin-top: 0.45rem;
            font-size: 0.78rem;
            color: #6c757d;
            font-weight: 600;
            word-break: break-word;
            text-align: center;
        }

        .snippet-placeholder {
            color: #adb5bd;
            font-size: 0.82rem;
            font-weight: 500;
        }

        .snippet-code {
            font-family: var(--bs-font-monospace);
            background: #ffffff;
            border: 1px solid rgba(33, 37, 41, 0.1);
            border-radius: 0.5rem;
            padding: 0.55rem 0.7rem;
            margin: 0;
            color: #495057;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        @media (max-width: 991.98px) {
            .snippet-cell+.snippet-cell {
                border-left: 0;
                border-top: 1px dashed rgba(33, 37, 41, 0.2);
            }
        }

        .avatar-xxl {
            width: 100% !important;
            max-width: 115px;
            height: 115px !important;
        }

        .avatar-title {
            width: 100%;
            height: 100%;
            display: flex !important;
            flex-direction: column !important;
            align-items: center !important;
            justify-content: center !important;
            box-sizing: border-box;
        }

        .avatar-title .fw-semibold {
            font-size: 0.72rem;
            max-width: 90px;
        }

        .inner-icon-item {
            width: 100%;
            display: flex;
            justify-content: center;
            transition: all 0.2s ease-in-out;
            cursor: pointer;
            position: relative;
        }

        .inner-icon-item:hover {
            transform: scale(1.05);
            z-index: 5;
        }

        .inner-icon-item:active {
            transform: scale(0.95);
        }

        .inner-icon-item .copied-badge {
            position: absolute;
            top: 8px;
            right: 8px;
            z-index: 10;
            font-size: 0.68rem;
            letter-spacing: 0.03em;
            padding: 0.2rem 0.45rem;
        }

        .inner-icon-item.is-selected .avatar-title {
            background-color: rgba(13, 110, 253, 0.08);
            border-color: rgba(13, 110, 253, 0.45) !important;
            box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.12);
        }
    </style>
@endsection

